// Image fixtures (spec story 12, Fixtures).
//
// Bytes are embedded (base64) so every vitest pool — including the
// Cloudflare workers pool, which has no filesystem access — can use
// them. Regenerate the source files with generate.mjs, then embed
// them with embed.mjs. The 10 MB / 10 MB + 1 byte bodies are
// generated in memory by the tests (making 20 MB of binary commit
// noise is not worth it).

export interface ImageFixture {
  name: string;
  type: string;
  bytes: Uint8Array;
}

function fromBase64(b64: string): Uint8Array {
  const binary = atob(b64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return bytes;
}

